  1	/**
  2	 * Unit tests for dispatchRoute() in gui/server.ts (WP-002).
  3	 *
  4	 * Exercises dispatchRoute() in isolation using a real createServer() / fetch
  5	 * pattern with synthetic Route arrays — no handleRequest(), no IncomingMessage
  6	 * or ServerResponse mocks.
  7	 *
  8	 * Verified scenarios:
  9	 *   AC-2: Query-parameter injection — handler receives URLSearchParams with expected entries.
 10	 *   AC-3: No query string — handler receives an empty URLSearchParams.
 11	 *   AC-4: noBody: true route — handler receives undefined as the body argument.
 12	 *   AC-5: statusCode: 204 route — HTTP 204 with an empty body.
 13	 *   AC-6: Handler throwing ApiError — mapped status code and error JSON.
 14	 *   AC-7: Handler throwing a generic Error — HTTP 500, INTERNAL_ERROR code,
 15	 *          process.stderr.write called.
 16	 */
 17	
 18	import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
 19	import { createServer } from 'node:http';
 20	import type { Server, IncomingMessage, ServerResponse } from 'node:http';
 21	
 22	import { dispatchRoute, apiErrorToStatus } from '../../gui/server.js';
 23	import { ApiError } from '../../gui/api.js';
 24	import type { Route } from '../../gui/server.js';
 25	
 26	// ---------------------------------------------------------------------------
 27	// Helpers
 28	// ---------------------------------------------------------------------------
 29	
 30	/**
 31	 * Starts a minimal test server that calls dispatchRoute() with the supplied
 32	 * route table. If no route matches, responds with HTTP 404. Listens on an
 33	 * ephemeral port (0) on loopback.
 34	 */
 35	function startDispatchServer(routes: Route[]): Promise<{ server: Server; baseUrl: string }> {
 36	  return new Promise((resolve, reject) => {
 37	    const server = createServer((req: IncomingMessage, res: ServerResponse) => {
 38	      const method = req.method?.toUpperCase() ?? 'GET';
 39	      const url = req.url ?? '/';
 40	
 41	      dispatchRoute(req, res, method, url, 0, routes).then((matched) => {
 42	        if (!matched) {
 43	          res.writeHead(404, { 'Content-Type': 'application/json' });
 44	          res.end(JSON.stringify({ error: { code: 'NOT_FOUND', message: 'no route matched' } }));
 45	        }
 46	      }).catch((err) => {
 47	        process.stderr.write(`[test-server] Unhandled: ${String(err)}\n`);
 48	        if (!res.headersSent) {
 49	          res.writeHead(500, { 'Content-Type': 'application/json' });
 50	          res.end(JSON.stringify({ error: { code: 'INTERNAL_ERROR', message: 'error' } }));
 51	        }
 52	      });
 53	    });
 54	
 55	    server.listen(0, '127.0.0.1', () => {
 56	      const addr = server.address();
 57	      if (addr && typeof addr === 'object') {
 58	        resolve({ server, baseUrl: `http://127.0.0.1:${addr.port}` });
 59	      } else {
 60	        reject(new Error('Could not determine server port'));
 61	      }
 62	    });
 63	
 64	    server.on('error', reject);
 65	  });
 66	}
 67	
 68	function stopServer(server: Server): Promise<void> {
 69	  return new Promise((resolve, reject) => {
 70	    server.close((err) => (err ? reject(err) : resolve()));
 71	  });
 72	}
 73	
 74	// ---------------------------------------------------------------------------
 75	// Test suite
 76	// ---------------------------------------------------------------------------
 77	
 78	describe('dispatchRoute() — WP-002', () => {
 79	  let server: Server;
 80	  let baseUrl: string;
 81	
 82	  afterEach(async () => {
 83	    if (server) await stopServer(server);
 84	    vi.restoreAllMocks();
 85	  });
 86	
 87	  // -------------------------------------------------------------------------
 88	  // AC-2: Query-parameter injection
 89	  // -------------------------------------------------------------------------
 90	
 91	  it('passes URLSearchParams with expected entries when query string is present', async () => {
 92	    let capturedQuery: URLSearchParams | undefined;
 93	
 94	    const routes: Route[] = [
 95	      {
 96	        method: 'GET',
 97	        path: '/test',
 98	        noBody: true,
 99	        handler: async (_body, _groups, query) => {
100	          capturedQuery = query;

101	          return { ok: true };
102	        },
103	      },
104	    ];
105	
106	    ({ server, baseUrl } = await startDispatchServer(routes));
107	
108	    const res = await fetch(`${baseUrl}/test?key=value&foo=bar`);
109	    expect(res.status).toBe(200);
110	    expect(capturedQuery).toBeInstanceOf(URLSearchParams);
111	    expect(capturedQuery!.get('key')).toBe('value');
112	    expect(capturedQuery!.get('foo')).toBe('bar');
113	  });
114	
115	  // -------------------------------------------------------------------------
116	  // AC-3: No query string — empty URLSearchParams
117	  // -------------------------------------------------------------------------
118	
119	  it('passes an empty URLSearchParams when there is no query string', async () => {
120	    let capturedQuery: URLSearchParams | undefined;
121	
122	    const routes: Route[] = [
123	      {
124	        method: 'GET',
125	        path: '/test',
126	        noBody: true,
127	        handler: async (_body, _groups, query) => {
128	          capturedQuery = query;
129	          return { ok: true };
130	        },
131	      },
132	    ];
133	
134	    ({ server, baseUrl } = await startDispatchServer(routes));
135	
136	    const res = await fetch(`${baseUrl}/test`);
137	    expect(res.status).toBe(200);
138	    expect(capturedQuery).toBeInstanceOf(URLSearchParams);
139	    expect([...capturedQuery!.entries()]).toHaveLength(0);
140	  });
141	
142	  // -------------------------------------------------------------------------
143	  // AC-4: noBody: true — handler receives undefined as the body argument
144	  // -------------------------------------------------------------------------
145	
146	  it('passes undefined as the body argument when noBody is true', async () => {
147	    let capturedBody: unknown = 'SENTINEL';
148	
149	    const routes: Route[] = [
150	      {
151	        method: 'POST',
152	        path: '/no-body',
153	        noBody: true,
154	        handler: async (body) => {
155	          capturedBody = body;
156	          return { ok: true };
157	        },
158	      },
159	    ];
160	
161	    ({ server, baseUrl } = await startDispatchServer(routes));
162	
163	    const res = await fetch(`${baseUrl}/no-body`, { method: 'POST' });
164	    expect(res.status).toBe(200);
165	    expect(capturedBody).toBeUndefined();
166	  });
167	
168	  // -------------------------------------------------------------------------
169	  // AC-5: statusCode: 204 — HTTP 204 with empty body
170	  // -------------------------------------------------------------------------
171	
172	  it('returns HTTP 204 with an empty body for a route with statusCode: 204', async () => {
173	    const routes: Route[] = [
174	      {
175	        method: 'DELETE',
176	        path: '/item',
177	        noBody: true,
178	        statusCode: 204,
179	        handler: async () => {
180	          return undefined;
181	        },
182	      },
183	    ];
184	
185	    ({ server, baseUrl } = await startDispatchServer(routes));
186	
187	    const res = await fetch(`${baseUrl}/item`, { method: 'DELETE' });
188	    expect(res.status).toBe(204);
189	    const text = await res.text();
190	    expect(text).toBe('');
191	  });
192	
193	  // -------------------------------------------------------------------------
194	  // AC-6: Handler throwing ApiError — mapped status code and error JSON
195	  // -------------------------------------------------------------------------
196	
197	  it('returns the mapped status code and error JSON when the handler throws ApiError', async () => {
198	    const routes: Route[] = [
199	      {
200	        method: 'GET',
201	        path: '/fail-api',
202	        noBody: true,
203	        handler: async () => {
204	          throw new ApiError('NOT_FOUND', 'Resource not found.');
205	        },
206	      },
207	    ];
208	
209	    ({ server, baseUrl } = await startDispatchServer(routes));
210	
211	    const res = await fetch(`${baseUrl}/fail-api`);
212	    expect(res.status).toBe(apiErrorToStatus('NOT_FOUND'));
213	    const body = (await res.json()) as { error: { code: string; message: string } };
214	    expect(body.error.code).toBe('NOT_FOUND');
215	    expect(body.error.message).toBe('Resource not found.');
216	  });
217	
218	  // -------------------------------------------------------------------------
219	  // AC-7: Handler throwing a generic Error — HTTP 500, INTERNAL_ERROR,
220	  //        process.stderr.write called
221	  // -------------------------------------------------------------------------
222	
223	  it('returns HTTP 500 with INTERNAL_ERROR and calls process.stderr.write for a generic Error', async () => {
224	    const stderrSpy = vi.spyOn(process.stderr, 'write').mockImplementation(() => true);
225	
226	    const routes: Route[] = [
227	      {
228	        method: 'GET',
229	        path: '/fail-generic',
230	        noBody: true,
231	        handler: async () => {
232	          throw new Error('something went wrong');
233	        },
234	      },
235	    ];
236	
237	    ({ server, baseUrl } = await startDispatchServer(routes));
238	
239	    const res = await fetch(`${baseUrl}/fail-generic`);
240	    expect(res.status).toBe(500);
241	    const body = (await res.json()) as { error: { code: string; message: string } };
242	    expect(body.error.code).toBe('INTERNAL_ERROR');
243	    expect(stderrSpy).toHaveBeenCalled();
244	    const stderrOutput = stderrSpy.mock.calls.map((args) => String(args[0])).join('');
245	    expect(stderrOutput).toMatch(/server/);
246	  });
247	});

1086	 * {@link parseQueryString} and passes the resulting `URLSearchParams` as the
1087	 * third argument to the matched handler.
1088	 *
1089	 * Returns `true` if a route was matched (caller should return immediately),
1090	 * or `false` if no route matched (caller should fall through).
1091	 */
1092	export async function dispatchRoute(
1093	  req: IncomingMessage,
1094	  res: ServerResponse,
1095	  method: string,
1096	  url: string,
1097	  port: number,
1098	  routes: Route[]
1099	): Promise<boolean> {
1100	  const [path] = url.split('?') as [string];
1101	  const query = parseQueryString(url);
1102	  for (const route of routes) {
1103	    if (route.method !== method) continue;
1104	    let groups: Record<string, string> | undefined;
1105	    if (typeof route.path === 'string') {
1106	      if (route.path !== path) continue;
1107	    } else {
1108	      const m = route.path.exec(path);
1109	      if (!m) continue;
1110	      groups = (m.groups ?? {}) as Record<string, string>;
1111	    }
1112	    try {
1113	      const body = route.noBody ? undefined : await readJsonBody(req);
1114	      const result = await route.handler(body, groups, query);
1115	      if (route.statusCode === 204) {
1116	        res.writeHead(204, { ...corsHeaders(port), ...securityHeaders() });
1117	        res.end();
1118	      } else {
1119	        sendJson(res, route.statusCode ?? 200, result, port);
1120	      }
1121	    } catch (err) {
1122	      if (err instanceof PayloadTooLargeError) {
1123	        sendError(res, 413, 'PAYLOAD_TOO_LARGE', 'Payload Too Large.', port);
1124	      } else if (err instanceof ApiError) {
1125	        sendError(res, apiErrorToStatus(err.code), err.code, err.message, port);
1126	      } else {
1127	        process.stderr.write(
1128	          `[server] Unhandled error in ${method} ${path}: ${String(err)}\n`
1129	        );
1130	        sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred.', port);
1131	      }
1132	    }
1133	    return true;
1134	  }
1135	  return false;
1136	}
1137	
1138	// ---------------------------------------------------------------------------
1139	// Main request handler
1140	// ---------------------------------------------------------------------------
1141	
1142	export async function handleRequest(
1143	  req: IncomingMessage,
1144	  res: ServerResponse,
1145	  ledgerRoot: string,
1146	  configPath: string,
1147	  port: number,
1148	  orchestratorLogsDir: string,
1149	  bootVersions: WorkspaceVersions | null = null
1150	): Promise<void> {
1151	  const method = req.method?.toUpperCase() ?? 'GET';
1152	  const url = req.url ?? '/';
1153	  const [path] = url.split('?') as [string];
1154	  const segments = path.split('/').filter(Boolean);
1155	  const isApiRequest = segments[0] === 'api';
1156	
1157	  // OPTIONS preflight
1158	  if (method === 'OPTIONS') {
1159	    res.writeHead(200, { ...corsHeaders(port), ...securityHeaders() });
1160	    res.end();
1161	    return;
1162	  }
1163	
1164	  // Static files
1165	  if (!isApiRequest) {
1166	    await serveStatic(req, res, port);
1167	    return;
1168	  }
1169	
1170	  // All API traffic is dispatched via the unified declarative route table.
1171	  // dispatchRoute() handles both body-parsing and body-free (noBody: true) routes.
1172	  // If no route matches, fall through to 404.
1173	  if (await dispatchRoute(
1174	    req, res, method, url, port,
1175	    buildRoutes(ledgerRoot, configPath, orchestratorLogsDir, bootVersions)
1176	  )) {
1177	    return;
1178	  }
1179	
1180	  sendError(res, 404, 'NOT_FOUND', 'Route not found.', port);
1181	}
1182	
1183	// ---------------------------------------------------------------------------
1184	// Server startup
1185	// ---------------------------------------------------------------------------

